import{_ as e,a0 as s,w as u,s as p,ao as a,I as t,x as i,a1 as n,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const S=JSON.parse('{"title":"Linux命令列中的幽默 | LCTT x X-CMD","titleTemplate":false,"description":"Linux命令列中的幽默 | LCTT (201507) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux命令列中的幽默 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux命令列中的幽默 | LCTT (201507) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201507/20150616 Linux Humor on the Command-line","title":"Linux命令列中的幽默","tag":"201507","desc":""},"relativePath":"201507/20150616 Linux Humor on the Command-line.md","filePath":"[post].md"}'),m={name:"201507/20150616 Linux Humor on the Command-line.md"};function d(w,l,x,g,f,T){const o=s("Link");return u(),p("div",null,[l[25]||(l[25]=a('<h1 id="linux命令列中的幽默" tabindex="-1">Linux命令列中的幽默 <a class="header-anchor" href="#linux命令列中的幽默" aria-label="Permalink to “Linux命令列中的幽默”">​</a></h1><p>圖形桌面總是很養眼的，它增強了可視化體驗，有時也能夠提升了某些軟件的功能，讓軟件變得更有趣。但是，在命令列下工作也不需要總是很古板，如果您想在命令列下尋找些樂趣，那麼有很多命令給您帶來趣味。</p><p>Linux是個有趣的操作系統。它提供大量的小型開源工具，從平淡無奇的軟件到稀奇古怪的應用。正是這些工具的功能和琳琅滿目的選擇幫助Linux脱穎而出。讓我們一起來看看下面這七個小工具吧。</p><h3 id="七彩虹-lolcat" tabindex="-1">七彩虹：lolcat <a class="header-anchor" href="#七彩虹-lolcat" aria-label="Permalink to “七彩虹：lolcat”">​</a></h3><p><img src="http://www.linuxlinks.com/portal/content/reviews/Misc/Screenshot-lolcat.png" alt="lolcat"></p><p>lolcat是一個用於將文件或標準輸入連接到標準輸出（類似常見的cat）的程序，但是它會為輸出添加七彩的顏色。</p><p>lolcat通常和其他諸如toilet或figlet等生成文本的應用結合使用。這個軟件不應被誤認為是一個或多個貓的圖像的宏。</p><p>lolcat由Moe編寫。</p>',8)),t("p",null,[l[1]||(l[1]=i("網址: ",-1)),n(o,{href:"https://github.com/busyloop/lolcat"},{default:r(()=>[...l[0]||(l[0]=[i("github.com",-1)])]),_:1})]),l[26]||(l[26]=a('<h3 id="牛郎的牛-cowsay" tabindex="-1">牛郎的牛：cowsay <a class="header-anchor" href="#牛郎的牛-cowsay" aria-label="Permalink to “牛郎的牛：cowsay”">​</a></h3><p><img src="http://www.linuxlinks.com/portal/content/reviews/Misc/Screenshot-cowsay.png" alt="cowsay"></p><p>cowsay是一個可配置的開源軟件，它用ASCII碼生成奶牛的圖片，並可以在對話氣泡中顯示消息。cowsay是用Perl寫的。</p><p>cowsay並不僅僅只能顯示奶牛。它能生成預先製作的圖片或者其他動物，包括鴨子、考拉、麋鹿、小馬、綿羊、劍龍和火雞，以及奶酪、雪人和骷髏。</p><p>有一個叫cowthink的應用，與對話的氣泡不同，它能在生成奶牛的同時生成思考的氣泡。</p><p>功能包括：</p><ul><li>讓腳本變得更有趣</li><li>Borg模式</li><li>可以更改奶牛看起來的樣子，比如讓奶牛看起來貪婪、偏執、固執、疲倦、古怪、年輕等</li><li>圖形版變體：xcowsay</li></ul>',7)),t("p",null,[l[3]||(l[3]=i("網址: ",-1)),n(o,{href:"https://web.archive.org/web/20120225123719/http://www.nog.net/%7Etony/warez/cowsay.shtml"},{default:r(()=>[...l[2]||(l[2]=[i("nog.net",-1)])]),_:1})]),l[27]||(l[27]=a('<h3 id="傻狗-doge" tabindex="-1">傻狗：doge <a class="header-anchor" href="#傻狗-doge" aria-label="Permalink to “傻狗：doge”">​</a></h3><p><img src="http://www.linuxlinks.com/portal/content/reviews/Misc/Screenshot-doge.png" alt="doge"></p><p>doge是一個簡單的每日信息腳本，它基於有些愚蠢但很有趣的doge的梗。它隨機的打印一些在語法上有誤的句子，有時這些句子基於您電腦中的東西。</p><p>doge是一個在2013年非常流行的互聯網潮流元素（梗）。這個梗通常由一幅日本柴犬的圖片和彩色的文字組成。這些文字故意用一種蹩腳的語氣寫成了一些互聯網的獨白。</p><ul><li>隨機的用不同的顏色和蹩腳的英語寫下隨機的句子</li><li>終端中的柴犬效果非常棒</li><li>可以獲得系統數據，比如主機名、運行中的程序、當前用户、$EDITOR</li><li>如果您安裝了lolcat，您可以用它作為點綴: <code>while true; do doge | lolcat -a -d 100 -s 100 -p 1; done</code></li><li>支持標準輸入: <code>ls /usr/bin | doge</code> 將顯示一些 /usr/bin下的可執行文件。哇噢，還有許多命令列的開關可以過濾詞語以及控制詞語的頻率。</li></ul>',5)),t("p",null,[l[5]||(l[5]=i("網址: ",-1)),n(o,{href:"https://github.com/thiderman/doge"},{default:r(()=>[...l[4]||(l[4]=[i("github.com/thiderman/doge",-1)])]),_:1})]),l[28]||(l[28]=a('<h3 id="水族箱-asciiquarium" tabindex="-1">水族箱：ASCIIQuarium <a class="header-anchor" href="#水族箱-asciiquarium" aria-label="Permalink to “水族箱：ASCIIQuarium”">​</a></h3><p><img src="http://www.linuxlinks.com/portal/content/reviews/Misc/Screenshot-Asciiquarium.png" alt="Asciiquarium"></p><p>ASCIIQuarium是一個以ASCII碼方式畫出的水族館/海洋動畫。享受生活在您電腦中水底的奇妙生物吧。</p><p>想運行ASCIIQuarium，您需要安裝Perl的curses包以及Term::Animation模組。請使用<code>sudo apt-get install libcurses-perl</code>來安裝前者，使用sudo cpan Term::Animation來安裝後者。兩個命令都需要在終端中運行。</p><p>功能包括：</p><ul><li>五彩的魚兒</li><li>有趣的動畫，包括釣魚鈎</li><li>還有許多的天鵝、鴨子、海豚和船隻</li></ul>',6)),t("p",null,[l[7]||(l[7]=i("網址: ",-1)),n(o,{href:"http://www.robobunny.com/projects/asciiquarium/html/"},{default:r(()=>[...l[6]||(l[6]=[i("www.robobunny.com",-1)])]),_:1})]),l[29]||(l[29]=t("h3",{id:"蒸汽機車-sl",tabindex:"-1"},[i("蒸汽機車：sl "),t("a",{class:"header-anchor",href:"#蒸汽機車-sl","aria-label":"Permalink to “蒸汽機車：sl”"},"​")],-1)),l[30]||(l[30]=t("p",null,[t("img",{src:"http://www.linuxlinks.com/portal/content/reviews/Misc/Screenshot-sl.png",alt:"sl"})],-1)),l[31]||(l[31]=t("p",null,"sl是一個有趣的終端應用，它為那些意外的錯將ls輸成sl的用户顯示一個動畫。",-1)),l[32]||(l[32]=t("p",null,"我打字通常非常草率，更喜歡速度而不是準確性。但錯別字在命令列中是非常危險的。因此sl扮演了一個提醒者，提醒我們注意錯誤輸入的這種壞習慣。它總是會讓人咯咯的笑。",-1)),l[33]||(l[33]=t("p",null,"功能包括：",-1)),l[34]||(l[34]=t("ul",null,[t("li",null,"使用 -F, 火車在飛翔"),t("li",null,"使用 -l, 顯示一個小型的火車"),t("li",null,"使用 -a, 看上去發生了意外")],-1)),t("p",null,[l[9]||(l[9]=i("網址: ",-1)),n(o,{href:"https://github.com/mtoyoda/sl"},{default:r(()=>[...l[8]||(l[8]=[i("github.com/mtoyoda/sl",-1)])]),_:1})]),l[35]||(l[35]=t("h3",{id:"火焰-aafire",tabindex:"-1"},[i("火焰：aafire "),t("a",{class:"header-anchor",href:"#火焰-aafire","aria-label":"Permalink to “火焰：aafire”"},"​")],-1)),l[36]||(l[36]=t("p",null,[t("img",{src:"http://www.linuxlinks.com/portal/content/reviews/Misc/Screenshot-aafire.png",alt:"aafire"})],-1)),l[37]||(l[37]=t("p",null,"aafire在終端中顯示燃燒的ASCII火焰。它展示了aalib庫的強大能力，一個ascii藝術庫顯示出來。",-1)),t("p",null,[l[11]||(l[11]=i("網址: ",-1)),n(o,{href:"http://aa-project.sourceforge.net/aalib/"},{default:r(()=>[...l[10]||(l[10]=[i("aa-project.sourceforge.net/aalib",-1)])]),_:1})]),l[38]||(l[38]=a('<h3 id="矩陣-cmatrix" tabindex="-1">矩陣：CMatrix <a class="header-anchor" href="#矩陣-cmatrix" aria-label="Permalink to “矩陣：CMatrix”">​</a></h3><p><img src="http://www.linuxlinks.com/portal/content/reviews/Misc/Screenshot-CMatrix.png" alt="CMatrix"></p><p>CMatrix是一個基於ncurses的程序，它模擬《黑客帝國》（一部電影）中的畫面。如果您在一個山洞裏度過了上個15年，那麼您可能不知道這部1999年的美國科幻電影，主角為 Keanu Reeves, Laurence Fishburne, Carrie-Anne Moss, Hugo Weaving和 Joe Pantoliano。</p><p>它可以在終端設置為132x300的情況下工作，並且可以以同樣的速率進行滾動或者以用户定義的速度進行異步的滾動。</p><p>功能包括：</p><ul><li>修改文本顏色</li><li>使用粗體字符</li><li>異步滾動</li><li>使用老式的滾動效果</li><li>屏幕保護程序模式</li></ul>',6)),t("p",null,[l[13]||(l[13]=i("網址: ",-1)),n(o,{href:"http://www.asty.org/cmatrix/"},{default:r(()=>[...l[12]||(l[12]=[i("www.asty.org/cmatrix",-1)])]),_:1})]),l[39]||(l[39]=t("hr",null,null,-1)),t("p",null,[l[15]||(l[15]=i("via: ",-1)),n(o,{href:"http://www.linuxlinks.com/article/20150614112018846/Humor.html"},{default:r(()=>[...l[14]||(l[14]=[i("http://www.linuxlinks.com/article/20150614112018846/Humor.html",-1)])]),_:1})]),t("p",null,[l[18]||(l[18]=i("譯者：",-1)),n(o,{href:"https://github.com/wwy-hust"},{default:r(()=>[...l[16]||(l[16]=[i("wwy-hust",-1)])]),_:1}),l[19]||(l[19]=i(" 校對：",-1)),n(o,{href:"https://github.com/carolinewuyan"},{default:r(()=>[...l[17]||(l[17]=[i("Caroline",-1)])]),_:1})]),t("p",null,[l[22]||(l[22]=i("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...l[20]||(l[20]=[i("LCTT",-1)])]),_:1}),l[23]||(l[23]=i(" 原創翻譯，",-1)),n(o,{href:"https://linux.cn/"},{default:r(()=>[...l[21]||(l[21]=[i("Linux中國",-1)])]),_:1}),l[24]||(l[24]=i(" 榮譽推出",-1))])])}const h=e(m,[["render",d]]);export{S as __pageData,h as default};
